import test from 'node:test';
import assert from 'node:assert/strict';
import {action,summary,settle,DAY} from '../src/engine.mjs';
import {authenticate,ADMIN_ID} from '../src/worker.mjs';
const now=Date.parse('2026-10-20T12:00:00Z');
const market={prices:{AAPL:{eur:100,at:now-3600000,fetchedAt:now}},rate:{annualPct:2.4,date:'2026-10-19',fetchedAt:now},events:[]};
const config={start:'2026-10-20',end:'2027-01-20',initial:10,salary:150,house:60,car:20,other:15,reserve:20,target:.6,title:'Bicicleta',reward:10};
const run=(s,a,t=now,m=market)=>action(s,m,{requestId:crypto.randomUUID(),...a},t);
const create=()=>run(null,{type:'setup',config});
test('monthly salary and bills are issued once; expenses and reserve protect available funds',()=>{let s=create();assert.equal(s.cash,160000);assert.equal(summary(s,market,now).available,45000);s=settle(s,market,now+DAY);assert.equal(s.cash,160000);assert.equal(s.bills.length,3);s=settle(s,market,Date.parse('2026-11-20T12:00Z'));assert.equal(s.cash,310000);assert.equal(s.bills.length,6)});
test('rejects unrealistic monthly goal, invalid amounts, unknown instruments, and reserve overspending',()=>{assert.throws(()=>run(null,{type:'setup',config:{...config,end:'2026-11-20',target:5}}),/exigente/);let s=run(create(),{type:'lesson',asset:'AAPL',answer:'risk'});for(const amount of [-1,'x',Infinity,100])assert.throws(()=>run(s,{type:'buy',asset:'AAPL',amount}));assert.throws(()=>run(s,{type:'buy',asset:'BOGUS',amount:1}));});
test('order waits for a future quote; same request cannot duplicate a trade',()=>{let s=run(create(),{type:'lesson',asset:'AAPL',answer:'risk'});const a={type:'buy',asset:'AAPL',amount:10,requestId:'idempotent-123'};s=run(s,a);assert.equal(s.orders.length,1);assert.equal(s.cash,160000);s=run(s,a);assert.equal(s.orders.length,1);s=settle(s,market,now+DAY);assert.equal(s.orders.length,1);const future={...market,prices:{AAPL:{eur:125,at:now+DAY,fetchedAt:now+DAY}}};s=settle(s,future,now+DAY);assert.equal(s.orders.length,0);assert.equal(s.holdings.AAPL.qty,.8);assert.equal(s.cash,150000);assert.equal(summary(s,future,now+DAY).returnPct,0)});
test('salary and extra contributions do not masquerade as returns; selling preserves performance',()=>{let s=run(create(),{type:'lesson',asset:'AAPL',answer:'risk'});s=run(s,{type:'buy',asset:'AAPL',amount:10});const p1={...market,prices:{AAPL:{eur:100,at:now+DAY,fetchedAt:now+DAY}}};s=settle(s,p1,now+DAY);const p2={...p1,prices:{AAPL:{eur:105,at:now+2*DAY,fetchedAt:now+2*DAY}}};s=settle(s,p2,now+2*DAY);assert.ok(Math.abs(summary(s,p2,now+2*DAY).returnPct-5)<1e-8);s=run(s,{type:'sell',asset:'AAPL'},now+2*DAY,p2);const p3={...p2,prices:{AAPL:{eur:105,at:now+3*DAY,fetchedAt:now+3*DAY}}};s=settle(s,p3,now+3*DAY);assert.equal(summary(s,p3,now+3*DAY).profit,500);assert.ok(Math.abs(summary(s,p3,now+3*DAY).returnPct-5)<1e-8)});
test('a deposit earns annualized interest and cannot outlive the challenge',()=>{let s=run(create(),{type:'lesson',asset:'DEPOSIT',answer:'locked'});assert.throws(()=>run(s,{type:'deposit',amount:10,term:180}),/vencer/);s=run(s,{type:'deposit',amount:10,term:30});assert.equal(s.deposits.length,1);s=settle(s,market,now+30*DAY);assert.equal(s.deposits.length,0);assert.equal(s.investmentCash,10019);assert.equal(summary(s,market,now+30*DAY).profit,19)});
test('stale data and unlearned assets cannot be traded; bills cannot be double paid',()=>{let s=create();assert.throws(()=>run(s,{type:'buy',asset:'AAPL',amount:1}),/ficha/);const id=s.bills[0].id;s=run(s,{type:'pay',billId:id});assert.throws(()=>run(s,{type:'pay',billId:id}),/pagada/);s=run(s,{type:'lesson',asset:'AAPL',answer:'risk'});assert.throws(()=>run(s,{type:'buy',asset:'AAPL',amount:1},now+6*DAY),/cotización/)});
test('auth requires verified server identity, not display name, role or email alone',async()=>{const request=new Request('https://bank.test/state',{headers:{Authorization:'Bearer '+'a'.repeat(30)}});const env={SUPABASE_URL:'https://auth.test',SUPABASE_PUBLISHABLE_KEY:'public'};const auth=u=>authenticate(request,env,async()=>Response.json(u));assert.equal(await auth({id:ADMIN_ID,email:'diegopenn@iCloud.com',email_confirmed_at:'date'}),true);assert.equal(await auth({id:'other',email:'diegopenn@icloud.com',email_confirmed_at:'date',user_metadata:{role:'admin'}}),false);assert.equal(await auth({id:ADMIN_ID,email:'other@example.com',email_confirmed_at:'date'}),false);assert.equal(await auth({id:ADMIN_ID,email:'diegopenn@icloud.com'}),false);assert.equal(await authenticate(new Request('https://bank.test'),env,()=>{throw Error('must not fetch')}),false)});
test('PWA serves the current private loader even when an old shell requests its old query tag; private API is never cached',async()=>{
 const {readFile}=await import('node:fs/promises'),{runInNewContext}=await import('node:vm');
 const source=await readFile(new URL('../../../sw.js',import.meta.url),'utf8');
 const listeners={},self={registration:{scope:'https://www.cocoenforma.com/'},location:{origin:'https://www.cocoenforma.com'},navigator:{userAgent:'Test'},addEventListener:(name,fn)=>listeners[name]=fn};
 const cache={match:async url=>url==='https://www.cocoenforma.com/coco-family-friendly-v160100.js'?new Response('fresh bootstrap'):undefined};
 runInNewContext(source,{self,URL,Request,Response,Headers,caches:{open:async()=>cache},fetch:()=>{throw Error('must use release cache')}});
 let response;listeners.fetch({request:new Request('https://www.cocoenforma.com/coco-family-friendly-v160100.js?v=old'),respondWith:p=>response=p});assert.equal(await (await response).text(),'fresh bootstrap');
 let intercepted=false;listeners.fetch({request:new Request('https://coco-bank-private.chatinmobiliario.workers.dev/state'),respondWith:()=>intercepted=true});assert.equal(intercepted,false);
});
